head.script:
scwin.onpageload = function() {
    inputCalendar1.setValue("2017");
};
scwin.onpageunload = function() {};
scwin.inputCalendar1_onviewchange = function(info) {
    if (localStorage.getItem('log') == "onviewchange") {
        localStorage.setItem("log", "onviewchange_onviewchange");
    } else {
        localStorage.setItem("log", "onviewchange");
    }
    console.log("inputCalendar1_onviewchange");
    WebSquare.logger.printLog("inputCalendar1_onviewchange");
};
scwin.checkLog = function() {
    //return WebSquare.logger.getErrorLog();
    var log = WebSquare.logger.getLog();
    var logStep3 = log.indexOf("inputCalendar1_onviewchange") > 0;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar1_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_header_btn_ok_yearType').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onviewchange'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
